★ 同样必须用 CTE 分开算：

WITH spend AS (
  SELECT SUM(cost) AS total FROM campaigns WHERE {条件}
),
net_gmv AS (
  SELECT SUM(o.amount) - COALESCE(SUM(r.refund_amount), 0) AS total
  FROM orders o
  JOIN campaigns c ON o.source_campaign_id = c.id
  LEFT JOIN refunds r ON r.order_id = o.id
  WHERE {条件} AND o.source_type = '达人'
)
SELECT net_gmv.total / spend.total AS 性价比 FROM net_gmv, spend;
